import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import Select from 'flarum/common/components/Select';
import { PERIODS } from './api';
import { t } from '../../utils/settings';
const SEARCH_DELAY_MS = 350;
/** 时间段、按名称搜索与总数：目录表格上方的工具栏。 */
export default class DirectoryControls extends Component {
  draft = null;
  onremove(vnode) {
    super.onremove(vnode);
    clearTimeout(this.searchTimer);
  }
  view() {
    const {
      state
    } = this.attrs;
    const options = Object.fromEntries(PERIODS.map(period => [period, t(`community.users.period.${period}`)]));
    return m("div", {
      className: "LcoyDirectory-controls"
    }, m("div", {
      className: "LcoyDirectory-filters"
    }, m(Select, {
      className: "LcoyDirectory-period",
      options: options,
      value: state.params.period || 'all',
      onchange: value => state.setPeriod(value),
      "aria-label": t('community.users.period_label')
    }), m("label", {
      className: "LcoyDirectory-search"
    }, m(Icon, {
      name: "fas fa-magnifying-glass"
    }), m("input", {
      className: "FormControl",
      type: "search",
      placeholder: t('community.users.search_placeholder'),
      "aria-label": t('community.users.search_placeholder'),
      value: this.draft ?? state.params.q ?? '',
      oninput: event => this.search(event.target.value)
    }))), state.total !== null && m("span", {
      className: "LcoyDirectory-total"
    }, t('community.users.total', {
      count: state.total
    })));
  }

  /** 搜索会等待用户停止输入：每个名称只发一次请求，而非每次按键。 */
  search(value) {
    this.draft = value;
    clearTimeout(this.searchTimer);
    this.searchTimer = setTimeout(() => {
      this.draft = null;
      this.attrs.state.refresh({
        q: value.trim()
      });
    }, SEARCH_DELAY_MS);
  }
}
flarum.reg.add('lcoy-roselle', 'forum/features/community/DirectoryControls', DirectoryControls);