import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import classList from 'flarum/common/utils/classList';
import formatNumber from 'flarum/common/utils/formatNumber';
import UserTile from './UserTile';
import { t } from '../../utils/settings';
import { shortAge } from '../../utils/dates';

/** 每一列的图标，与 Discourse 目录表头的一致。 */
const COLUMN_ICONS = {
  likesReceived: 'fas fa-heart',
  likesGiven: 'fas fa-heart'
};

/** 行数据中自带的数值列（其他列取自用户模型）。 */
const NUMERIC = ['likesReceived', 'likesGiven', 'topicCount', 'postCount', 'daysVisited', 'postsRead'];
/**
 * Discourse 的目录表格：左侧为用户名，每个数值占一列，表头可点击
 * 排序，末尾有“加载更多”。
 *
 * “最后访问”始终显示（当用户公开该信息时），但仅对有核心权限的
 * 用户可排序——服务端会告知哪些列可排序。
 */
export default class DirectoryTable extends Component {
  view() {
    const {
      state,
      emptyText
    } = this.attrs;
    const columns = this.displayColumns();
    if (state.failed && !state.rows.length) {
      return m("p", {
        className: "LcoyCommunity-empty"
      }, t('community.load_error'));
    }
    if (!state.loading && !state.rows.length && state.total !== null) {
      return m("p", {
        className: "LcoyCommunity-empty"
      }, state.params.q ? t('community.users.no_results') : emptyText);
    }
    return m("div", {
      className: "LcoyDirectory"
    }, m("div", {
      className: "LcoyCommunity-tableWrap"
    }, m("table", {
      className: "LcoyCommunity-table LcoyDirectory-table"
    }, m("thead", null, m("tr", null, this.header('username', t('community.users.column.username'), 'LcoyDirectory-userCol'), columns.map(column => this.header(column, t(`community.users.column.${column}`), 'LcoyCommunity-num')))), m("tbody", null, state.rows.map(row => this.row(row, columns))))), state.loading && m(LoadingIndicator, {
      display: "block"
    }), !state.loading && state.hasMore && m("div", {
      className: "LcoyCommunity-more"
    }, m(Button, {
      className: "Button",
      onclick: () => state.loadMore()
    }, t('community.load_more'))));
  }

  /** 服务端返回的列，外加“最后访问”（若服务端未按此列排序）。 */
  displayColumns() {
    const columns = [...this.attrs.state.columns];
    if (!columns.includes('lastSeenAt')) columns.push('lastSeenAt');
    return columns;
  }
  header(column, label, className) {
    const {
      state
    } = this.attrs;
    const sortable = column === 'username' || state.columns.includes(column);
    const active = state.currentOrder() === column;
    const icon = COLUMN_ICONS[column];
    const content = m('[', null, icon && m(Icon, {
      name: icon,
      className: "LcoyDirectory-columnIcon"
    }), m("span", null, label), active && m(Icon, {
      name: state.params.dir === 'asc' ? 'fas fa-chevron-up' : 'fas fa-chevron-down',
      className: "LcoyDirectory-sortIcon"
    }));
    return m("th", {
      className: classList(className, `LcoyDirectory-col--${column}`, {
        'is-sorted': active
      }),
      "aria-sort": active ? state.params.dir === 'asc' ? 'ascending' : 'descending' : undefined,
      scope: "col"
    }, sortable ? m("button", {
      type: "button",
      className: "LcoyDirectory-sort",
      onclick: () => state.sortBy(column)
    }, content) : m("span", {
      className: "LcoyDirectory-sort is-static"
    }, content));
  }
  row(row, columns) {
    const user = row.model;
    const isMe = app.session.user === user;
    return m("tr", {
      key: row.user,
      className: classList({
        'is-me': isMe
      })
    }, m("td", {
      className: "LcoyDirectory-userCol"
    }, m(UserTile, {
      user: user,
      size: "small"
    })), columns.map(column => m("td", {
      className: `LcoyCommunity-num LcoyDirectory-value LcoyDirectory-col--${column}`,
      "data-label": t(`community.users.column.${column}`)
    }, this.value(row, column))));
  }
  value(row, column) {
    if (NUMERIC.includes(column)) {
      const value = row[column];
      return typeof value === 'number' ? formatNumber(value) : '-';
    }
    if (column === 'lastSeenAt') {
      const seen = row.model.lastSeenAt();
      return seen ? m("time", {
        datetime: seen.toISOString(),
        title: seen.toLocaleString()
      }, shortAge(seen)) : '-';
    }
    return null;
  }
}
flarum.reg.add('lcoy-roselle', 'forum/features/community/DirectoryTable', DirectoryTable);